// Every delivered review, flagged is_new when its review_id has not been seen before (workflow static data).
const MAX_KEYS = 5000;                       // review ids remembered between runs (oldest dropped)
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const seen = new Set(store.seen);
const rows = $input.all().map(i => i.json).filter(r => r.type === 'review' && r.review_id);
rows.sort((a, b) => String(b.review_date || '').localeCompare(String(a.review_date || '')));
const clip = (s, n) => { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const today = new Date().toISOString().slice(0, 10);
const out = rows.map(r => {
  const id = String(r.review_id);
  const is_new = !seen.has(id);
  if (is_new) { seen.add(id); store.seen.push(id); }
  return { json: {
    review_id: id,
    hotel_name: String(r.hotel_name || '').split(',')[0],
    location_id: r.location_id || '',
    rating: r.rating,
    title: r.title || '',
    text: clip(r.text, 300),
    review_date: String(r.review_date || '').slice(0, 10),
    stay_date: String(r.stay_date || '').slice(0, 7),
    trip_type: /^(family|couples|solo|business|friends)$/.test(String(r.trip_type || '').toLowerCase()) ? String(r.trip_type).toLowerCase() : '',
    reviewer_name: r.reviewer_name || '',
    reviewer_hometown: r.reviewer_hometown || '',
    response_status: r.response ? 'answered' : 'unanswered',
    url: r.url || r.hotel_url || '',
    is_new,
    fetched_on: today,
  } };
});
if (store.seen.length > MAX_KEYS) store.seen = store.seen.slice(-MAX_KEYS);
return out;
